final class SalesPhoneGatewayService {
    private const OPTION='ckm_sales_phone_gateway_v1';
    private const HEARTBEAT='ckm_sales_phone_gateway_heartbeat_v1';
    private const CALLS='ckm_sales_phone_gateway_calls_v1';
    private const MAX_CALLS=300;
    private const ONLINE_TTL=45;
    private const COMMAND_TTL=120;

